const CAMPOS = [["6a92da4b8490fde669082a69","Nome"],["6a92da4b8490fde669082a6a","WhatsApp"],["6a92da4b8490fde669082a6b","Instagram"],["6a92da4b8490fde669082a6c","E-mail"],["6a92da4b8490fde669082a6e","Faturamento mensal"],["6a92da4b8490fde669082a6d","Ticket da mentoria"],["6a92da4b8490fde669082a76","Agendamentos/mês hoje"],["6a92dcda8490fde669082a96","Agendamentos desejados/mês"],["6a92dc8ec7270f5d1f0c51d6","Como gera agendamentos"],["6a92dc7b8490fde669082a94","O que mais frustra"],["6a92dc16c7270f5d1f0c51d5","Calls/mês (qualificadas)"],["6a92dc0f7c86920578073b58","Já rodou tráfego / investe quanto"],["6a92dbfc7c86920578073b57","Tem gestor de tráfego"],["6a92da4b8490fde669082a77","Disponível pra investir"],["6a92da4b8490fde669082a70","Por que agora"],["6a92da4b8490fde669082a71","Por que deveríamos aceitar"]];
const resp = $('Trata Webhook').item.json.response || {};
const ans = resp.answers || {};
const val = (id) => { const c = ans[id]?.content; if (c === null || c === undefined) return ''; if (c === true) return 'Sim'; if (c === false) return 'Não'; return Array.isArray(c) ? c.filter(Boolean).join(', ') : String(c); };
const linhas = CAMPOS.map(([id, rot]) => { const v = val(id); return v ? `*${rot}:* ${v}` : null; }).filter(Boolean);
const t = resp.tracking || {};
const utmLines = ['utm_source','utm_campaign','utm_medium','utm_content','utm_term']
  .filter(k => t[k])
  .map(k => `_${k}:_ ${t[k]}`);
const hora = Number(new Intl.DateTimeFormat('pt-BR', { timeZone: 'America/Sao_Paulo', hour: '2-digit', hourCycle: 'h23' }).format(new Date()));
const saudacao = hora < 12 ? 'Bom dia' : hora < 18 ? 'Boa tarde' : 'Boa noite';
const ticketValue = val('6a92da4b8490fde669082a6d');
let origens = '\n\n*📍 Origem:* Formulário: Agenda lotada ou não paga (yay forms)';
if (utmLines.length) origens += '\n' + utmLines.join('\n');
const resumo = linhas.join('\n\n') + origens;
return [{ json: { ...$json, resumo, saudacao, leadPhone: val('6a92da4b8490fde669082a6a'), ticketValue } }];

const ans = $('Trata Webhook').item.json.response.answers || {};
// ✅ ID correto do campo Calendly
const c = ans['6a98254c18ff935d3e018546']?.content;
const link = (typeof c === 'string' && c.includes('calendly.com')) ? c.trim() : null;
let eventUuid = null;
if (link) {
  const m = link.match(/scheduled_events\/([0-9a-fA-F-]{36})/);
  if (m) eventUuid = m[1];
}
return [{ json: { ...$json, agendou: !!eventUuid, calendlyLink: link, eventUuid } }];

const ev = $('3 · Busca evento (por link)').item.json.resource;
const p = new Intl.DateTimeFormat('pt-BR', { timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(new Date(ev.start_time));
const g = (t) => p.find((x) => x.type === t).value;
const dataHora = `${g('day')}/${g('month')} às ${g('hour')}:${g('minute')}`;
return [{ json: { ...$json, evento: ev, dataHora } }];

// ⚠️ Preencha nome, e-mail (Calendly) e telefone de cada closer
const CLOSERS = {
  'carol.livolis@gmail.com':        { nome: 'Carol',     phone: 'TELEFONE_DA_CAROL' },
  'email_do_diogo@exemplo.com':     { nome: 'Diogo',     phone: '5527996120736' },
  'email_do_tiago@exemplo.com':     { nome: 'Tiago',     phone: '5534984133437' },
  'email_do_matheus@exemplo.com':   { nome: 'Matheus',   phone: '5545999553235' },
  'email_do_guilherme@exemplo.com': { nome: 'Guilherme', phone: '5531992265968' }
};

const ev = $('4 · Dados do evento').item.json.evento;
const eventName = (ev.name || '').toLowerCase();
const memberships = ev.event_memberships || [];
const userEmail = (memberships[0]?.user_email || '').toLowerCase().trim();

const closerData = CLOSERS[userEmail] || null;
const closerPhone = closerData?.phone || null;

// Se não é CG10 nem CG20 → agenda do Alan (≤20k)
const isLowTicket = !eventName.includes('cg10') && !eventName.includes('cg20');
const closerNome = isLowTicket ? 'Alan (agenda ≤20k)' : (closerData?.nome || userEmail || '⚠️ não mapeado');

return [{ json: { ...$json, closerEmail: userEmail, closerPhone, closerNome, isLowTicket, eventName } }];

